// ============================================================================
// CONFIGURATION & ZERO-KEY DEMO MODE
// Set DEMO_MODE = false when you connect your Apify API credentials.
// ============================================================================
const DEMO_MODE = false;
const MAX_RUN_BUDGET_USD = 1.00; // Hard cap per execution ($0.05 per company checked)
const TARGET_ROLE_KEYWORDS = ['engineer', 'developer', 'devops', 'sales', 'account executive', 'vp', 'director', 'growth', 'data', 'security'];
const EXCLUDE_COMPANY_KEYWORDS = ['staffing', 'recruiting', 'talent agency', 'headhunter'];

const watchList = [
  { domain: 'vercel.com', company_name: 'Vercel', target_region: 'US/Remote' },
  { domain: 'linear.app', company_name: 'Linear', target_region: 'US/EU' },
  { domain: 'PostHog.com', company_name: 'PostHog', target_region: 'Global' },
  { domain: 'elite-staffing-agency.example', company_name: 'Elite Recruiting Partners', target_region: 'US' }
];

// Step 1: Normalize domains, deduplicate, and filter out staffing agencies ($0 cost)
const seen = new Set();
const validTargets = [];
const skipped = [];

for (const row of watchList) {
  const cleanDomain = String(row.domain || '').toLowerCase().replace(/^https?:\/\//, '').replace(/\/.*$/, '').trim();
  const compName = String(row.company_name || '');
  if (!cleanDomain || seen.has(cleanDomain)) continue;
  seen.add(cleanDomain);

  const isAgency = EXCLUDE_COMPANY_KEYWORDS.some(k => compName.toLowerCase().includes(k) || cleanDomain.includes(k));
  if (isAgency) {
    skipped.push({ domain: cleanDomain, reason: 'Excluded Staffing/Recruiting Agency' });
    continue;
  }
  validTargets.push({
    domain: cleanDomain,
    company_name: compName,
    target_region: row.target_region || 'Any'
  });
}

// Step 2: Enforce Upfront Budget Ceiling
const maxCompaniesAllowed = Math.floor(MAX_RUN_BUDGET_USD / 0.05);
const budgetApprovedTargets = validTargets.slice(0, maxCompaniesAllowed);

return budgetApprovedTargets.map((t, idx) => ({
  json: {
    ...t,
    demo_mode: DEMO_MODE,
    target_role_keywords: TARGET_ROLE_KEYWORDS,
    budget_guardrail: {
      max_run_budget_usd: MAX_RUN_BUDGET_USD,
      estimated_company_cost_usd: 0.05,
      batch_index: idx + 1,
      batch_total_approved: budgetApprovedTargets.length,
      estimated_total_run_usd: Number((budgetApprovedTargets.length * 0.05).toFixed(2)),
      skipped_agencies_count: skipped.length
    }
  }
}));

// ============================================================================
// STATEFUL DELTA & DIFF ENGINE
// Distinguishes: NEW_ROLE_OPENED | ROLE_CLOSED | NO_CHANGE | SOURCE_ERROR
// Never wipes previous jobs if an endpoint temporarily fails!
// ============================================================================
const staticData = $getWorkflowStaticData('global');
if (!staticData.jobStateByDomain) {
  staticData.jobStateByDomain = {};
}

const items = $input.all();
const output = [];

for (const item of items) {
  const d = item.json;
  const domain = String(d.domain || d.company_domain || 'unknown').toLowerCase();
  const prevJobs = staticData.jobStateByDomain[domain] || {};

  // 1. Check if scrape failed or source was unreachable
  const sourceError = Boolean(d.error || d.status === 'error' || d.source_available === false);
  if (sourceError) {
    output.push({
      json: {
        domain,
        delta_status: 'SOURCE_ERROR',
        action_required: false,
        message: 'ATS endpoint unreachable on this run. Previous state preserved to avoid false close alerts.',
        new_roles_count: 0,
        closed_roles_count: 0,
        new_target_roles: []
      }
    });
    continue;
  }

  // 2. Parse current open jobs
  const rawJobs = Array.isArray(d.jobs) ? d.jobs : (Array.isArray(d.open_roles) ? d.open_roles : []);
  const currentMap = {};
  const newRoles = [];
  const newTargetRoles = [];
  const roleKeywords = Array.isArray(d.target_role_keywords) ? d.target_role_keywords : ['engineer', 'sales', 'vp', 'director', 'developer', 'growth'];

  for (const job of rawJobs) {
    const jobId = String(job.id || job.job_id || job.url || job.title || '').trim();
    if (!jobId) continue;
    const title = String(job.title || 'Untitled Role');
    const location = String(job.location || 'Remote/Unspecified');
    const applyUrl = String(job.url || job.apply_url || '');

    currentMap[jobId] = { title, location, applyUrl, last_seen: new Date().toISOString() };

    if (!prevJobs[jobId]) {
      newRoles.push(currentMap[jobId]);
      const matchesTarget = roleKeywords.some(k => title.toLowerCase().includes(k));
      if (matchesTarget) {
        newTargetRoles.push(currentMap[jobId]);
      }
    }
  }

  // 3. Detect closed roles (existed in previous healthy run, absent today)
  const closedRoles = [];
  for (const [oldId, oldJob] of Object.entries(prevJobs)) {
    if (!currentMap[oldId]) {
      closedRoles.push(oldJob);
    }
  }

  // 4. Persist updated state
  staticData.jobStateByDomain[domain] = currentMap;

  const deltaStatus = newTargetRoles.length > 0
    ? 'NEW_ROLE_OPENED'
    : (closedRoles.length > 0 ? 'ROLE_CLOSED' : 'NO_CHANGE');

  // Deterministic Outreach Brief (Zero LLM Token Cost!)
  const topRole = newTargetRoles[0];
  const deterministicHook = topRole
    ? `Noticed ${domain} just opened a new ${topRole.title} role (${topRole.location}) — teams scaling that function usually need automated pipeline coverage.`
    : '';

  output.push({
    json: {
      domain,
      ats_platform: d.ats_provider || d.platform || 'Public ATS',
      delta_status: deltaStatus,
      action_required: deltaStatus === 'NEW_ROLE_OPENED',
      total_active_jobs: Object.keys(currentMap).length,
      new_roles_count: newRoles.length,
      new_target_roles_count: newTargetRoles.length,
      closed_roles_count: closedRoles.length,
      new_target_roles: newTargetRoles.slice(0, 5),
      closed_roles: closedRoles.slice(0, 5),
      deterministic_icebreaker: deterministicHook,
      checked_at: new Date().toISOString()
    }
  });
}

return output;
